<?php
require __DIR__.'/report_api.php';
$date=auditDate(filter_input(INPUT_GET,'date'));$window=filter_input(INPUT_GET,'window');$window=in_array($window,array('all','s1','s2','s3','day'),true)?$window:'all';
$loom=auditLoom(filter_input(INPUT_GET,'loom'));$exclude=auditIds(filter_input(INPUT_GET,'exclude'));$include=$loom?array($loom):array();
list($start,$end)=auditWindow($date,$window);$dataset=auditDataset($db,$start,$end,$include,$exclude);$report=auditMeasure($dataset,$start,$end);$summary=auditSummary($report);
$codes=$window==='all'?array('s1','s2','s3'):array($window);$labels=array('s1'=>'07:00–15:00','s2'=>'15:00–23:00','s3'=>'23:00–07:00','day'=>'00:00–24:00');$shifts=array();
foreach($codes as $code){list($a,$b)=auditWindow($date,$code);$r=auditMeasure($dataset,$a,$b);$s=auditSummary($r);$affected=0;foreach($r['rows'] as $row)if($row['stopCount']||$row['stopSeconds'])$affected++;$shifts[]=array('code'=>$code,'label'=>$labels[$code],'count'=>$s['stopCount'],'seconds'=>$s['stopSeconds'],'looms'=>$r['quality']['hasRecords']?$affected:null);}
$problems=array();foreach($report['rows'] as $r)if($r['stopCount']||$r['stopSeconds'])$problems[]=array('loomId'=>$r['loomId'],'loomName'=>$r['loomName'],'count'=>$r['stopCount'],'seconds'=>$r['stopSeconds']);
if($report['quality']['complete'])usort($problems,function($a,$b){return $b['seconds']-$a['seconds'];});
$causeRows=auditCauseRows($db,$report);$causes=array();$categories=array();
foreach($causeRows as $r){$code=$r['statusCode'];if(!isset($causes[$code]))$causes[$code]=array('code'=>$code,'cause'=>$r['cause'],'count'=>0,'seconds'=>0);$causes[$code]['count']+=$r['stopCount'];$causes[$code]['seconds']+=$r['stopSeconds'];$category=in_array($code,array(1,15,16))?'Çözgü':($code>=2&&$code<=14?'Atkı':($code===20?'Koni':($code===18?'Manuel':'Diğer')));if(!isset($categories[$category]))$categories[$category]=array('category'=>$category,'count'=>0,'seconds'=>0);$categories[$category]['count']+=$r['stopCount'];$categories[$category]['seconds']+=$r['stopSeconds'];}
$history=array();$historyName='';
if($loom&&!in_array($loom,$exclude,true)){$hStart=clone $date;$hStart->modify('-13 days');list($hs,)=auditWindow($hStart,$window);$hData=auditDataset($db,$hs,$end,$include,$exclude);foreach($hData['machines'] as $m)$historyName=$loom.' '.$m['NomeTelaio'];for($d=clone $hStart;$d<=$date;$d->modify('+1 day')){list($a,$b)=auditWindow($d,$window);$r=auditMeasure($hData,$a,$b);$s=auditSummary($r);$history[]=array('date'=>$d->format('Y-m-d'),'count'=>$s['stopCount'],'seconds'=>$s['stopSeconds']);}}
$machineSql='';$args=array();if($loom){$machineSql.=' AND t.IdTelaio=?';$args[]=$loom;}if($exclude){$machineSql.=' AND t.IdTelaio NOT IN ('.implode(',',array_fill(0,count($exclude),'?')).')';$args=array_merge($args,$exclude);}
$live=auditExec($db,"SELECT t.IdTelaio loomId,t.NomeTelaio loomName,t.Online online,r.Timestamp lastUpdate,TIMESTAMPDIFF(SECOND,r.Timestamp,NOW()) ageSeconds,r.ProduzioneEffettuata actualValue,r.ProduzioneDesiderata targetValue,r.Armatura1 patternName,r.Velocita speed,r.Resa efficiency FROM telaio t LEFT JOIN dato_rt r ON r.IdTelaio=t.IdTelaio WHERE t.EnableTelaio=1 AND t.IdTelaio<>100".$machineSql,$args);
$offline=array();$goals=array();$patterns=array();
foreach($live as $r){$age=$r['ageSeconds']===null?null:(int)$r['ageSeconds'];$fresh=$r['online']==1&&$age!==null&&$age>=0&&$age<=60;
if(!$fresh){$offline[]=array('loomId'=>(int)$r['loomId'],'loomName'=>$r['loomName'],'lastUpdate'=>$r['lastUpdate'],'ageSeconds'=>$age,'state'=>$r['online']!=1?'Bağlantı yok':'Veri güncel değil');continue;}
if((float)$r['targetValue']>0)$goals[]=array('loomId'=>(int)$r['loomId'],'loomName'=>$r['loomName'],'actual'=>(float)$r['actualValue'],'target'=>(float)$r['targetValue'],'percent'=>round($r['actualValue']*100/$r['targetValue'],1));
$pattern=trim($r['patternName'])?:'Tanımsız';if(!isset($patterns[$pattern]))$patterns[$pattern]=array('pattern'=>$pattern,'looms'=>0,'speed'=>0,'efficiency'=>0);$patterns[$pattern]['looms']++;$patterns[$pattern]['speed']+=(float)$r['speed'];$patterns[$pattern]['efficiency']+=(float)$r['efficiency']/100;}
foreach($patterns as &$p){$p['speed']=round($p['speed']/$p['looms'],1);$p['efficiency']=round($p['efficiency']/$p['looms'],2);}unset($p);
echo json_encode(array('date'=>$date->format('Y-m-d'),'window'=>$window,'loomId'=>$loom,'excludedLoomIds'=>$exclude,'summary'=>array('count'=>$summary['stopCount'],'seconds'=>$summary['stopSeconds'],'offlineCount'=>count($offline),'goalCount'=>count($goals)),'shifts'=>$shifts,'problems'=>$problems,'causes'=>array_values($causes),'categories'=>array_values($categories),'history'=>array('loomName'=>$historyName,'rows'=>$history),'offline'=>$offline,'goals'=>$goals,'patterns'=>array_values($patterns),'liveAsOf'=>date('Y-m-d H:i:s',$dataset['now']),'quality'=>$report['quality']),JSON_UNESCAPED_UNICODE);